// Ingestion, Normalization & Validation Node
// Normalizes leads into 13 consistent fields
// Validates: name, email, company, job_title
// Missing optional fields become 'Unknown' without hallucination

let inputItems = $input.all();
let rawLeads = [];

if (inputItems.length === 1 && inputItems[0].json.leads && Array.isArray(inputItems[0].json.leads)) {
  rawLeads = inputItems[0].json.leads;
} else if (inputItems.length === 1 && (!inputItems[0].json || Object.keys(inputItems[0].json).length === 0)) {
  // Realistic demo leads for testing
  rawLeads = [
    {
