// Multi-tier Follow-up Engine
// Follow-up #1 -> Follow-up #2 -> Mark Cold / Nurture

const item = $input.first();
const lead = item.json;
const firstName = (lead.lead_name || 'there').split(' ')[0];

const followUp1 = {
  cadence: 'Day +3',
  subject: `Re: ${lead.email_subject || 'Following up on lead automation'}`,
  body: `Hi ${firstName},\n\nChecking in quickly on my previous message regarding ${lead.company}'s challenge with: ${lead.pain_point}.\n\nI know things get busy, but our AI SDR platform recently helped a similar team cut triage time by 80%.\n\nWould a 10-minute coffee chat this Thursday work for you?\n\nBest,\nSales Team`,
  sent_at: new Date(Date.now() + 3 * 86400000).toISOString()
};

const followUp2 = {
  cadence: 'Day +7',
  subject: `Final touchpoint: AI Lead Qualification for ${lead.company}`,
  body: `Hi ${firstName},\n\nSince I haven't heard back, I assume this isn't a top priority for ${lead.company} right now.\n\nI'll step back and archive your record so I don't clutter your inbox. If you ever want to revisit automating ${lead.pain_point}, feel free to reach out anytime.\n\nWishing you all the best,\nSales Team`,
  sent_at: new Date(Date.now() + 7 * 86400000).toISOString()
};

return [{
  json: {
    ...lead,
    status: 'Marked_Cold_Nurture',
    follow_up_stage: 'Follow-up #2 Complete',
    follow_up_1: followUp1,
    follow_up_2: followUp2,
    final_cadence_status: 'Exhausted_Cadence_Moved_To_Nurture',
    closed_reason: 'No response after 2 follow-ups',
    updated_at: new Date().toISOString()
  }
}];

// AI Response Sentiment & Intent Analysis
// Analyzes inbound prospect response and classifies intent: Interested | Not Interested | Unclear

const item = $input.first();
const lead = item.json;

const responseText = (lead.prospect_reply_text || lead.response_status || '').toLowerCase();

let sentiment = 'Unclear';
let interestLevel = 'Medium';
let objection = 'None';
let nextStep = 'Sales Rep Clarification';

if (responseText.includes('pricing') || responseText.includes('demo') || responseText.includes('interested') || responseText.includes('yes') || responseText.includes('sounds like what we need') || responseText.includes('thursday') || lead.simulation_response === 'Interested') {
  sentiment = 'Interested';
  interestLevel = 'High';
  objection = 'None';
  nextStep = 'Schedule 30-min Executive Demo & Send Pricing Deck';
} else if (responseText.includes('unsubscribe') || responseText.includes('not interested') || responseText.includes('remove') || responseText.includes('stop') || lead.simulation_response === 'Not Interested') {
  sentiment = 'Not Interested';
  interestLevel = 'Zero';
  objection = 'No current need / Do not contact';
  nextStep = 'Remove from active list and mark Closed Lost';
} else {
  sentiment = 'Unclear';
  interestLevel = 'Low';
  objection = 'Ambiguous reply or out-of-office';
  nextStep = 'Manual SDR Review';
}

return [{
  json: {
    ...lead,
    response_sentiment: sentiment,
    response_interest_level: interestLevel,
    detected_objection: objection,
    recommended_sales_action: nextStep,
    is_interested: sentiment === 'Interested',
    updated_at: new Date().toISOString()
  }
}];
